#include <stdio.h>
#include <stdlib.h>

#define INF 1000000001LL

int cmp(const void *a, const void *b) {
    char ca = *(const char*)a;
    char cb = *(const char*)b;
    return (ca > cb) - (ca < cb);
}

int main() {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);

    char pattern[505];
    scanf("%s", pattern);

    char words[505][27];
    for (int i = 0; i < M; i++) {
        scanf("%s", words[i]);
        qsort(words[i], K, sizeof(char), cmp);
    }

    long long P;
    scanf("%lld", &P);

    long long powK[505];
    powK[0] = 1;
    for (int i = 1; i <= M; i++) {
        if (powK[i - 1] > INF / K) {
            powK[i] = INF;
        } else {
            powK[i] = powK[i - 1] * K;
            if (powK[i] > INF) powK[i] = INF;
        }
    }

    char result[505];
    int pos = 0;
    int idx = 0;

    for (int i = 0; i < N; i++) {
        if (pattern[i] == '#') {
            long long block = powK[M - idx - 1];
            char chosen = words[idx][K - 1];

            for (int j = 0; j < K; j++) {
                if (P > block) {
                    P -= block;
                } else {
                    chosen = words[idx][j];
                    break;
                }
            }

            result[pos++] = chosen;
            idx++;
        } else {
            result[pos++] = pattern[i];
        }
    }

    result[pos] = '\0';
    printf("%s\n", result);

    return 0;
}
